#pragma once
// An INI of float tunables over a table generated by gen_settings.py (one row per [section] key, with
// its built-in default). Shared by SKYBDeg::Settings and Persuasion::Settings.
//
// Load() reads the file; ReloadIfChanged() reads it again when its write time changed. SetOverride (the
// settings menu's store) replaces one INI value; an override survives reloads.
#include "Platform/IniFile.h"
#include "Platform/Text.h"

#include <array>
#include <filesystem>
#include <format>
#include <optional>
#include <string>
#include <string_view>

template <const auto& kDefs>
class IniTable
{
public:
	static constexpr std::size_t kCount = std::size(kDefs);
	using Values = std::array<float, kCount>;

	// a_name starts the log lines: "<name> settings: ...".
	constexpr IniTable(std::string_view a_path, std::string_view a_name) :
		_path(a_path), _name(a_name) {}

	[[nodiscard]] float         Get(std::size_t a_index) const { return _values[a_index]; }
	[[nodiscard]] const Values& All() const { return _values; }

	// ("Decay", "WhileOpen") -> the row index, or -1 when the table has no such row.
	[[nodiscard]] static int Find(std::string_view a_section, std::string_view a_key)
	{
		for (std::size_t i = 0; i < kCount; ++i) {
			if (Text::IEquals(a_section, kDefs[i].section) && Text::IEquals(a_key, kDefs[i].key)) {
				return static_cast<int>(i);
			}
		}
		return -1;
	}

	void Load()
	{
		for (std::size_t i = 0; i < kCount; ++i) {
			_ini[i] = kDefs[i].fallback;
		}

		const auto  time = Text::WriteTime(_path);
		const auto  source = std::format("{} settings", _name);
		std::size_t read = 0, changed = 0;
		const bool  opened = IniFile::Read(_path, source, [&](const IniFile::Entry& a_entry) {
			const int idx = Find(a_entry.section, a_entry.key);
			if (idx < 0) {
				Log::WARN("{}: unknown key [{}] {} (line {}) - ignored", source, a_entry.section, a_entry.key, a_entry.line);
				return;
			}
			float v = 0.0f;
			if (!Text::Parse(a_entry.value, v)) {
				Log::WARN("{}: [{}] {} = '{}' is not a number (line {}) - default {} kept", source, a_entry.section, a_entry.key,
					a_entry.value, a_entry.line, kDefs[idx].fallback);
				return;
			}
			_ini[static_cast<std::size_t>(idx)] = v;
			++read;
			if (v != kDefs[idx].fallback) {
				++changed;
				Log::INFO("{}: [{}] {} = {} (default {})", source, a_entry.section, a_entry.key, v, kDefs[idx].fallback);
			}
		});
		_time = opened ? time : std::nullopt;
		if (opened) {
			Log::INFO("{}: {} read {} of {} values, {} differ from the defaults", source, _path, read, kCount, changed);
		} else {
			Log::WARN("{}: {} not found - every value uses its built-in default", source, _path);
		}
		Recompose();
	}

	// Re-reads the INI if it changed on disk since the last read.
	void ReloadIfChanged()
	{
		if (Text::WriteTime(_path) == _time) {
			return;
		}
		Log::INFO("{} settings: {} changed on disk - reloading", _name, _path);
		Load();
	}

	bool SetOverride(std::string_view a_section, std::string_view a_key, float a_value)
	{
		const int idx = Find(a_section, a_key);
		if (idx < 0) {
			Log::WARN("settings menu: {} has no key [{}] {} - ignored", _name, a_section, a_key);
			return false;
		}
		const auto i = static_cast<std::size_t>(idx);
		if (!_overrides[i] || *_overrides[i] != a_value) {
			Log::INFO("settings menu: {} [{}] {} = {} (INI {})", _name, kDefs[i].section, kDefs[i].key, a_value, _ini[i]);
		}
		_overrides[i] = a_value;
		_values[i] = a_value;
		return true;
	}

private:
	// _values = INI values with the overrides laid over them
	void Recompose()
	{
		std::size_t n = 0;
		for (std::size_t i = 0; i < kCount; ++i) {
			_values[i] = _overrides[i] ? *_overrides[i] : _ini[i];
			n += _overrides[i] ? 1 : 0;
		}
		if (n) {
			Log::INFO("{} settings: {} value(s) set by the settings menu override the INI", _name, n);
		}
	}

	std::string_view                                _path;
	std::string_view                                _name;
	Values                                          _values{};
	Values                                          _ini{};
	std::array<std::optional<float>, kCount>        _overrides{};
	std::optional<std::filesystem::file_time_type>  _time;
};
